namespace sarif;









using docking.widgets;
using ghidra.app.events;
using ghidra.app.plugin.core.graph;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.util;
using ghidra.service.graph;
using ghidra.service.graph;
using ghidra.service.graph;
using ghidra.service.graph;

/**
 * {@link GraphDisplayListener} that handle events back and from program
 * graphs.
 */
public class SarifGraphDisplayListener : AddressBasedGraphDisplayListener {

	private Map<Address, Set<AttributedVertex>> map = new();
	private SarifController controller;
	private AttributedGraph graph;

	public SarifGraphDisplayListener(SarifController controller, GraphDisplay display, AttributedGraph graph) : base(controller.getPlugin().getTool(), controller.getProgram(), display)
    {
		this.controller = controller;
		this.graph = graph;
		foreach (AttributedVertex vertex in graph.vertexSet()) {
			string addrStr = vertex.getAttribute("Address");
			if (addrStr != null) {
				Address address = program.getAddressFactory().getAddress(addrStr);
				Set<AttributedVertex> set = map.get(address);
				if (set == null) {
					set = new();
				}
				set.add(vertex);
				map.put(address, set);
			}
		}
	}

	/* @Override */
	public void eventSent(PluginEvent @event) {
		base.eventSent(@event);
		if (@event is ProgramLocationPluginEvent) {
			ProgramLocationPluginEvent ev = (ProgramLocationPluginEvent) @event;
			if (program.equals(ev.getProgram())) {
				ProgramLocation location = ev.getLocation();
				Set<AttributedVertex> vertices = getVertices(location.getAddress());
				if (vertices != null) {
					graphDisplay.selectVertices(vertices, EventTrigger.INTERNAL_ONLY);
				}
			}
		}
	}

	/* @Override */
	public void selectionChanged(Set<AttributedVertex> vertices) {
		base.selectionChanged(vertices);
		controller.setSelection(vertices);
	}
	
	/* @Override */
	public Address getAddress(AttributedVertex vertex) {
		string addrStr = vertex.getAttribute("Address");
		Address address = program.getAddressFactory().getAddress(addrStr);
		return address;
	}

	protected Set<AttributedVertex> getVertices(Address address) {
		return map.get(address);
	}

	/* @Override */
	protected Set<AttributedVertex> getVertices(AddressSetView addrSet) {
		if (addrSet.isEmpty()) {
			return Collections.emptySet();
		}

		Set<AttributedVertex> vertices = new();
		foreach (Entry<Address, Set<AttributedVertex>> entry in map.entrySet()) {
			if (addrSet.contains(entry.getKey())) {
				foreach (AttributedVertex v in entry.getValue()) {
					vertices.add(v);
				}
			}
		}
		return vertices;
	}

	/* @Override */
	protected AddressSet getAddresses(Set<AttributedVertex> vertices) {

		AddressSet addrSet = new AddressSet();
		Collection<Set<AttributedVertex>> values = map.values();
		foreach (Set<AttributedVertex> set in values) {
			foreach (AttributedVertex vertex in vertices) {
				if (set.contains(vertex)) {
					string addrStr = vertex.getAttribute("Address");
					Address address = program.getAddressFactory().getAddress(addrStr);
					addrSet.add(address);
				}
			}
		}
		return addrSet;
	}

	protected bool isValidAddress(Address addr) {
		if (addr == null || program == null) {
			return false;
		}
		return program.getMemory().contains(addr) || addr.isExternalAddress();
	}

	/* @Override */
	public GraphDisplayListener cloneWith(GraphDisplay newGraphDisplay) {
		return new SarifGraphDisplayListener(controller, newGraphDisplay, graph);
	}

}
